import { useColorMode } from "@kobalte/core";
import type { Component, ComponentProps } from "solid-js";

import { Toaster as Sonner } from "solid-sonner";
import IconAlert02 from "~icons/hugeicons/alert-02";
import IconCancelCircle from "~icons/hugeicons/cancel-circle";
import IconCheckmarkCircle02 from "~icons/hugeicons/checkmark-circle-02";
import IconInformationCircle from "~icons/hugeicons/information-circle";
import IconLoading03 from "~icons/hugeicons/loading-03";

type ToasterProps = ComponentProps<typeof Sonner>;

const Toaster: Component<ToasterProps> = (props) => {
  const { colorMode } = useColorMode();

  return (
    <Sonner
      theme={colorMode()}
      class="group toaster"
      icons={{
        success: <IconCheckmarkCircle02 class="size-4" />,
        info: <IconInformationCircle class="size-4" />,
        warning: <IconAlert02 class="size-4" />,
        error: <IconCancelCircle class="size-4" />,
        loading: <IconLoading03 class="size-4 animate-spin" />,
      }}
      style={{
        "--normal-bg": "var(--popover)",
        "--normal-text": "var(--popover-foreground)",
        "--normal-border": "var(--border)",
        "--border-radius": "var(--radius)",
      }}
      toastOptions={{
        classes: {
          toast: "cn-toast",
        },
      }}
      {...props}
    />
  );
};

export { Toaster };
